-- Workflow 11A (contracts-11a, then foundation-11a): the Workflow's one migration, regenerated by
-- drizzle-kit at each foundation-11a checkpoint (never a 0036; Stage 1a amendment 7).
-- organizations.connect_inbound (C231.10; decision 71): the organisation receives Connect connections
-- only while it is on; off for every organisation until its admin turns it on.
-- (C) C230.5: connect_connections (organisation-scoped, one per ordered pair; agreement_reference
-- sealed for the row), connect_share_policies (versions, never updated) and connect_share_tokens
-- (the source environment's; categories fixed at creation; one consent record per token).
-- (R) C230.5 (review F08): provenance on inquiries, verifications and files, connect_provenance on
-- verification_checks, hydrated_fields on accounts, inquiries and transactions, and relied_on_cloned
-- with share_token_id on inquiry_decisions; every row before it reads null (false for the flag).
-- (K) C230.5, C236: consent_records (both sides; the evidence and an attested text sealed for the
-- row) and consent_texts (one per environment and digest; the body sealed for <environment id>:<sha256>),
-- and the share tokens' foreign keys to the records they cite.
CREATE TABLE "connect_connections" (
	"id" text PRIMARY KEY NOT NULL,
	"source_organization_id" text NOT NULL,
	"destination_organization_id" text NOT NULL,
	"status" text NOT NULL,
	"creator_type" text NOT NULL,
	"creator_id" text NOT NULL,
	"current_policy_id" text,
	"accepted_policy_id" text,
	"agreement_reference" text,
	"activated_at" timestamp with time zone,
	"activated_by_user_id" text,
	"deactivated_at" timestamp with time zone,
	"deactivated_by" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "connect_connections_id_format" CHECK ("connect_connections"."id" ~ '^cxn_[0-9A-HJKMNP-TV-Z]{26}$'),
	CONSTRAINT "connect_connections_status_valid" CHECK ("connect_connections"."status" in ('pending', 'active', 'inactive', 'archived')),
	CONSTRAINT "connect_connections_creator_type_valid" CHECK ("connect_connections"."creator_type" in ('user', 'api-key')),
	CONSTRAINT "connect_connections_deactivated_by_valid" CHECK ("connect_connections"."deactivated_by" is null or "connect_connections"."deactivated_by" in ('source', 'destination')),
	CONSTRAINT "connect_connections_deactivated" CHECK (("connect_connections"."deactivated_at" is null) = ("connect_connections"."deactivated_by" is null)),
	CONSTRAINT "connect_connections_activated" CHECK ("connect_connections"."activated_by_user_id" is null or "connect_connections"."activated_at" is not null)
);
--> statement-breakpoint
CREATE TABLE "connect_share_policies" (
	"id" text PRIMARY KEY NOT NULL,
	"connection_id" text NOT NULL,
	"version" integer NOT NULL,
	"body" jsonb NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_by_type" text NOT NULL,
	"created_by_id" text NOT NULL,
	CONSTRAINT "connect_share_policies_connection_id_version_key" UNIQUE("connection_id","version"),
	CONSTRAINT "connect_share_policies_connection_id_id_key" UNIQUE("connection_id","id"),
	CONSTRAINT "connect_share_policies_id_format" CHECK ("connect_share_policies"."id" ~ '^cxnp_[0-9A-HJKMNP-TV-Z]{26}$'),
	CONSTRAINT "connect_share_policies_version_positive" CHECK ("connect_share_policies"."version" >= 1),
	CONSTRAINT "connect_share_policies_created_by_type_valid" CHECK ("connect_share_policies"."created_by_type" in ('user', 'api-key'))
);
