	"explicit_biometric" boolean DEFAULT false NOT NULL,
	"peek_count" integer DEFAULT 0 NOT NULL,
	"status" text NOT NULL,
	"expiry_reason" text,
	"failure_reason" text,
	"redeem_mode" text,
	"destination_type" text,
	"destination_id" text,
	"destination_consent_record_id" text,
	"reserved_inquiry_id" text,
	"redeem_summary" jsonb,
	"creator_type" text NOT NULL,
	"creator_id" text NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"pending_at" timestamp with time zone,
	"redeemed_at" timestamp with time zone,
	"expired_at" timestamp with time zone,
	"failed_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "connect_share_tokens_environment_id_id_key" UNIQUE("environment_id","id"),
	CONSTRAINT "connect_share_tokens_id_format" CHECK ("connect_share_tokens"."id" ~ '^cnst_[0-9A-HJKMNP-TV-Z]{26}$'),
	CONSTRAINT "connect_share_tokens_consent_record_id_format" CHECK ("connect_share_tokens"."consent_record_id" ~ '^cnsr_[0-9A-HJKMNP-TV-Z]{26}$'),
	CONSTRAINT "connect_share_tokens_destination_consent_record_id_format" CHECK ("connect_share_tokens"."destination_consent_record_id" is null or "connect_share_tokens"."destination_consent_record_id" ~ '^cnsr_[0-9A-HJKMNP-TV-Z]{26}$'),
	CONSTRAINT "connect_share_tokens_environment_kind_valid" CHECK ("connect_share_tokens"."environment_kind" in ('sandbox', 'production')),
	CONSTRAINT "connect_share_tokens_source_type_valid" CHECK ("connect_share_tokens"."source_type" in ('inquiry', 'account', 'transaction', 'verification')),
	CONSTRAINT "connect_share_tokens_source_id_format" CHECK (case source_type when 'inquiry' then source_id ~ '^inq_[0-9A-HJKMNP-TV-Z]{26}$' when 'account' then source_id ~ '^acc_[0-9A-HJKMNP-TV-Z]{26}$' when 'transaction' then source_id ~ '^txn_[0-9A-HJKMNP-TV-Z]{26}$' when 'verification' then source_id ~ '^ver_[0-9A-HJKMNP-TV-Z]{26}$' else false end),
	CONSTRAINT "connect_share_tokens_data_categories_valid" CHECK ("connect_share_tokens"."data_categories" <@ array['identity-fields', 'contact-fields', 'other-fields', 'document-images', 'biometric', 'check-results']::text[]),
	CONSTRAINT "connect_share_tokens_peek_count_non_negative" CHECK ("connect_share_tokens"."peek_count" >= 0),
	CONSTRAINT "connect_share_tokens_status_valid" CHECK ("connect_share_tokens"."status" in ('created', 'pending', 'redeemed', 'expired', 'failed')),
	CONSTRAINT "connect_share_tokens_expiry_reason_valid" CHECK ("connect_share_tokens"."expiry_reason" is null or "connect_share_tokens"."expiry_reason" in ('time', 'source_expired', 'connection_deactivated', 'consent_withdrawn')),
	CONSTRAINT "connect_share_tokens_failure_reason_valid" CHECK ("connect_share_tokens"."failure_reason" is null or "connect_share_tokens"."failure_reason" in ('source_not_found', 'source_redacted', 'import_failed', 'unrecoverable_error', 'connection_inactive', 'consent_withdrawn', 'consent_expired', 'consent_scope_exceeded', 'source_is_copy')),
	CONSTRAINT "connect_share_tokens_redeem_mode_valid" CHECK ("connect_share_tokens"."redeem_mode" is null or "connect_share_tokens"."redeem_mode" in ('clone', 'hydrate', 'fill-inquiry')),
	CONSTRAINT "connect_share_tokens_destination_type_valid" CHECK ("connect_share_tokens"."destination_type" is null or "connect_share_tokens"."destination_type" in ('inquiry', 'account', 'transaction', 'verification')),
	CONSTRAINT "connect_share_tokens_creator_type_valid" CHECK ("connect_share_tokens"."creator_type" in ('user', 'api-key', 'workflow')),
	CONSTRAINT "connect_share_tokens_expired" CHECK (("connect_share_tokens"."status" = 'expired') = ("connect_share_tokens"."expired_at" is not null) and ("connect_share_tokens"."expired_at" is null) = ("connect_share_tokens"."expiry_reason" is null)),
	CONSTRAINT "connect_share_tokens_failed" CHECK (("connect_share_tokens"."status" = 'failed') = ("connect_share_tokens"."failed_at" is not null) and ("connect_share_tokens"."failed_at" is null) = ("connect_share_tokens"."failure_reason" is null)),
	CONSTRAINT "connect_share_tokens_redeemed" CHECK (("connect_share_tokens"."status" = 'redeemed') = ("connect_share_tokens"."redeemed_at" is not null))
);
