	CONSTRAINT "consent_records_withdrawn_via_valid" CHECK ("consent_records"."withdrawn_via" is null or "consent_records"."withdrawn_via" in ('api', 'operator', 'flow')),
	CONSTRAINT "consent_records_withdrawal_reason_valid" CHECK ("consent_records"."withdrawal_reason" is null or "consent_records"."withdrawal_reason" in ('subject-request', 'operator-decision', 'other'))
);
